var QUIZ={};
QUIZ.nd1=[{"q":"用整体法分析多物体系统时，以下哪项正确？","o":["整体法只能分析静止系统","整体法不考虑系统内物体间的内力","整体法必须对每个物体单独分析","整体法不能处理有加速度的系统"],"a":1,"e":"整体法将多个物体视为整体，内力是系统内物体间的力，在整体分析中不必考虑。","c":"内力在整体法中不出场，这是它最大的优势。","t":"整体法"},{"q":"隔离法分析问题的核心思路是？","o":["忽略所有接触力","从系统中选取一个物体单独受力分析","只分析重力","把所有物体看成一个整体"],"a":1,"e":"隔离法是从系统中选取单个物体，分析它受到的所有外力，用于求物体间的相互作用力。","c":"选对研究对象，题目就解决了一半。","t":"隔离法"},{"q":"用整体法分析叠放物体时，水平力F拉下方物体，两物体一起加速运动，以下说法正确的是：","o":["整体法可以求出两物体间的摩擦力","整体法只需求系统受到的外力","整体法不能用于有摩擦的系统","整体法必须知道每个物体的质量"],"a":1,"e":"整体法不考虑内力，二物体间的摩擦力是内力，只分析外力：拉力F、地面摩擦力和支持力。","c":"内力是内部矛盾，整体法不关心内部事务。","t":"整体法应用"},{"q":"连接体问题的标准解题策略是？","o":["直接用隔离法分析每个物体","先整体求加速度，再隔离求内力","只用整体法","只用力学公式"],"a":1,"e":"先整体得到共同加速度，再隔离分析求物体间的作用力，这是连接体问题的标准解法。","c":"这个套路掌握了，一堆连接体题都能快速解决。","t":"连接体策略"},{"q":"AB叠放，F拉B向右加速，A随B一起加速，A受摩擦力方向是？","o":["向左","向右","无摩擦力","向上"],"a":1,"e":"A的加速度由B对A的摩擦力提供（f=mA·a），方向与加速度方向相同，向右。","c":"摩擦力不一定是阻力——当它让物体加速时，它是动力。","t":"摩擦力方向"},{"q":"质量为m的物体，F作用产生加速度a，F变为2F时a变为？","o":["a/2","a","2a","4a"],"a":2,"e":"根据F=ma，a与F成正比，F加倍则a加倍：a'=2F/m=2a。","c":"F=ma中力和加速度是正比关系，这是最基本的物理思想。","t":"F=ma正比"},{"q":"2kg物体受10N合力，a=？","o":["2m/s²","5m/s²","10m/s²","20m/s²"],"a":1,"e":"a=F/m=10/2=5m/s²。","c":"这个直接代公式就能算对。","t":"F=ma计算"},{"q":"体重计示数大于真实体重时，电梯处于？","o":["匀速上升","匀速下降","加速上升或减速下降","加速下降或减速上升"],"a":2,"e":"示数大于重力说明超重，加速度向上。加速上升和减速下降的加速度都向上。","c":"超重失重看加速度方向，不看速度方向。","t":"超重失重"}];
QUIZ.nd2=[{"q":"受力分析的标准顺序是？","o":["先分析推力再分析重力","按重力-弹力-摩擦力的顺序","只分析运动方向的力","先假设力的方向再判断"],"a":1,"e":"受力分析顺序：一重二弹三摩擦。重力一定存在，弹力看接触，摩擦力看相对运动。","c":"按顺序来就不会漏力，这是基本功。","t":"受力分析顺序"},{"q":"物体静止在斜面上，受几个力？","o":["2个","3个","4个","5个"],"a":1,"e":"受重力(竖直向下)、支持力(垂直斜面向上)、静摩擦力(沿斜面向上)三个力。“下滑力”是重力的分力，不是独立力。","c":"“下滑力”从你的受力分析里删掉，物理会好很多。","t":"斜面受力"},{"q":"水平拉力F拉物体在粗糙面匀速运动，受几个力？","o":["2","3","4","5"],"a":2,"e":"受重力、支持力、拉力F、滑动摩擦力，共4个力，平衡。","c":"匀速也是平衡态——很多人只记得静止才平衡。","t":"匀速平衡"},{"q":"互相垂直的3N和4N，合力大小？","o":["1N","5N","7N","12N"],"a":1,"e":"F=√(3²+4²)=5N。","c":"勾股定理在物理中经常出现。","t":"力的合成"},{"q":"以下哪个力不是按性质命名的？","o":["重力","弹力","摩擦力","支持力"],"a":3,"e":"重力、弹力、摩擦力按力的性质命名；支持力按效果命名，本质是弹力。","c":"区分性质力和效果力是物理分类思维的第一步。","t":"力的分类"},{"q":"物体随传送带匀速运动，摩擦力方向？","o":["向前","向后","无摩擦力","向上"],"a":2,"e":"匀速运动水平方向无相对运动趋势，不受摩擦力。","c":"传送带不一定有摩擦力，关键看有没有相对运动趋势。","t":"传送带摩擦力"},{"q":"两球悬挂静止，上端绳子拉力为？","o":["mg","2mg","mg/2","0"],"a":1,"e":"整体法：系统受2mg重力和绳拉力T，T=2mg。","c":"整体法让这道题变成了一秒题。","t":"整体法平衡"},{"q":"物体沿粗糙斜面匀速下滑，倾角满足？","o":["tanθ=μ","sinθ=μ","cosθ=μ","μ=0"],"a":0,"e":"mgsinθ=μmgcosθ，化简得tanθ=μ。","c":"这个结论记熟，斜面题快很多。","t":"斜面自锁"}];
